  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 The Gold and Salt Empires of West Africa$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "West Africa held rich lands between the Sahara Desert and the forests of the coast. Its great wealth came from gold and from trade across the Sahara. Salt, needed for life, came from the desert, and gold came from the south. Camel caravans carried both, along with cloth, copper, ivory and slaves, and traders brought Islam along the routes.\n\nGhana, home of the Soninke people, grew powerful from about the 300s to the 1000s. Its kings taxed the gold and salt trade from their capital, Koumbi Saleh. Pressure from the Almoravids, a Muslim Berber movement, and drought weakened Ghana by about 1076.\n\nMali rose next. Sundiata Keita defeated a rival around 1235 and built an empire. Its most famous ruler was Mansa Musa, a devout Muslim who made a pilgrimage to Mecca in 1324. He gave so much gold on the way that its value fell in Cairo. He brought back scholars and architects, and Timbuktu became a center of trade, learning and Islamic study.\n\nSonghai grew from the city of Gao. Sunni Ali built a strong army and took Timbuktu. Askia Muhammad organized the government and promoted learning. In 1591 a Moroccan army with firearms defeated Songhai at Tondibi, and the empire broke apart.\n\nProverbs 22:1 says, A good name is rather to be chosen than great riches, and loving favour rather than silver and gold.\n\nYour task: (1) Explain what gold and salt had to do with Ghana's power. (2) Tell two facts about Mansa Musa. (3) Tell why Songhai fell.\n\nFlorida standards: SS.912.W.3.9, SS.912.W.3.10, SS.912.W.3.11.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.9, SS.912.W.3.10, SS.912.W.3.11", "script": "Welcome to Unit 4. Listen, the continent of Africa holds some of the most remarkable stories in world history. West Africa held rich lands between the Sahara Desert and the forests of the coast. Its wealth came from gold and from trade across the desert. Salt, needed for life, came from the desert, and gold came from the south. Camel caravans carried both, along with cloth, copper, ivory and slaves, and traders carried Islam along the routes.\n\nNow watch this. Ghana, home of the Soninke people, rose from about the three hundreds to the ten hundreds. Its kings taxed the gold and salt trade from their capital, Koumbi Saleh. Pressure from the Almoravids and drought weakened Ghana by about ten seventy six.\n\nLook at this. Mali rose next. Sundiata Keita defeated a rival around twelve thirty five and built an empire. Its most famous ruler, Mansa Musa, a devout Muslim, made a pilgrimage to Mecca in thirteen twenty four. He gave away so much gold that its value fell in Cairo. He brought back scholars and architects, and Timbuktu became a center of trade and learning.\n\nThen came Songhai, from the city of Gao. Sunni Ali built a strong army and took Timbuktu. Askia Muhammad organized the government and promoted learning. In fifteen ninety one a Moroccan army with firearms defeated Songhai at Tondibi, and the empire broke apart.\n\nProverbs twenty two and one says, A good name is rather to be chosen than great riches, and loving favour rather than silver and gold.\n\nYour task today. Explain gold and salt in Ghana's power. Tell two facts about Mansa Musa. And tell why Songhai fell. Take the four question check.\n\nGreatness is more than gold. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 The Gold and Salt Empires of West Africa$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Ethiopia, the Swahili Coast, Great Zimbabwe and Kongo$j$, $j${"readings": [{"title": "Psalm 68 (King James Version)", "url": "/portal/bible/Psalms/68"}], "body": "Africa's eastern, central and southern regions also built strong states.\n\nEthiopia: The kingdom of Axum became Christian in the 300s under King Ezana, making it one of the oldest Christian lands in the world. Ethiopia kept its faith after the rise of Islam. Around 1200 King Lalibela had remarkable churches carved out of solid rock. Psalm 68:31 says, Princes shall come out of Egypt; Ethiopia shall soon stretch out her hands unto God.\n\nThe Swahili Coast: Along the Indian Ocean, city states such as Kilwa, Mombasa and Mogadishu traded gold, ivory, and other goods with Arabia, Persia, India and China using monsoon winds. The Swahili language and culture blended African and Arab influence.\n\nGreat Zimbabwe: In southern Africa, the Shona people built a large capital with great stone walls between the 1100s and 1400s, rich from cattle and the gold trade.\n\nKongo: In central Africa, the Kingdom of Kongo was well organized, with a king and provinces. In the late 1400s Portuguese traders arrived, and its king Afonso I accepted Christianity and tried to protect his people from enslavement.\n\nWhat caused the decline? Portuguese attacks on coastal cities, the growth of the Atlantic slave trade, changes in trade routes, rivalry among states, and wars weakened these kingdoms.\n\nYour task: (1) Tell what is special about Ethiopia's faith. (2) Name two Swahili cities and what they traded. (3) Give two reasons African states declined.\n\nFlorida standards: SS.912.W.3.12, SS.912.W.3.13, SS.912.W.3.14.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.12, SS.912.W.3.13, SS.912.W.3.14", "script": "Welcome back. Listen, Africa's eastern, central and southern regions also built strong states. In Ethiopia, the kingdom of Axum became Christian in the three hundreds under King Ezana, one of the oldest Christian lands on earth. Ethiopia kept its faith even after Islam arose. Around twelve hundred, King Lalibela had remarkable churches carved out of solid rock. Psalm sixty eight and thirty one says, Princes shall come out of Egypt; Ethiopia shall soon stretch out her hands unto God.\n\nNow watch this. Along the Indian Ocean coast, city states such as Kilwa, Mombasa and Mogadishu traded gold and ivory with Arabia, Persia, India and China, riding the monsoon winds. The Swahili language and culture blended African and Arab influence.\n\nLook at this. In southern Africa the Shona people built a large capital with great stone walls, Great Zimbabwe, between the eleven hundreds and the fourteen hundreds, rich from cattle and gold. In central Africa the Kingdom of Kongo was well organized with a king and provinces. In the late fourteen hundreds Portuguese traders arrived, and King Afonso the First accepted Christianity and tried to protect his people from enslavement.\n\nWhat caused decline? Portuguese attacks on coastal cities, the growth of the Atlantic slave trade, shifts in trade routes, rivalry among states and wars all weakened these kingdoms.\n\nYour task today. Tell what is special about Ethiopia's faith. Name two Swahili cities and what they traded. And give two reasons African states declined. Take the four question check.\n\nGod has had witnesses on every continent. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Ethiopia, the Swahili Coast, Great Zimbabwe and Kongo$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 The Olmec, Zapotec, Chavin and Maya$j$, $j${"readings": [{"title": "Psalm 8 (King James Version)", "url": "/portal/bible/Psalms/8"}], "body": "Long before Europeans arrived, great civilizations grew in the Americas. Corn, beans and squash fed them.\n\nThe Olmec lived on the Gulf Coast of Mexico from about 1200 BC. They carved huge stone heads, built ceremonial centers and traded widely. Many call them the mother culture of Mesoamerica. The Zapotec built Monte Alban, a mountaintop city in Oaxaca, around 500 BC, and used an early writing system. In the Andes of Peru, the Chavin culture, from about 900 BC, centered on the temple of Chavin de Huantar, spread art and religion, and prepared the way for later Andean peoples.\n\nThe Maya lived in southern Mexico, Guatemala and Belize. They built independent city states such as Tikal and Copan, with tall stepped pyramids. They developed a writing system of glyphs, a calendar, and a number system with the idea of zero. Maya astronomers tracked the sun, moon and planets. Psalm 8:3 says, When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained. Around 900 many southern Maya cities were abandoned. Scholars point to drought, war, overuse of land and political collapse, though debate continues.\n\nYour task: (1) Match each culture to a place: Olmec, Zapotec, Chavin. (2) Name three Maya achievements. (3) Explain two theories about the Maya decline.\n\nFlorida standards: SS.912.W.3.15, SS.912.W.3.16, SS.912.W.3.17.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.15, SS.912.W.3.16, SS.912.W.3.17", "script": "Welcome back. Listen, long before Europeans arrived, great civilizations grew in the Americas, fed by corn, beans and squash.\n\nNow watch this. The Olmec lived on the Gulf Coast of Mexico from about twelve hundred before Christ. They carved huge stone heads, built ceremonial centers and traded widely. Many call them the mother culture of Mesoamerica. The Zapotec built Monte Alban, a mountaintop city in Oaxaca, around five hundred before Christ, and used an early form of writing. In the Andes of Peru the Chavin culture, from about nine hundred before Christ, centered on the temple of Chavin de Huantar and spread art and religion.\n\nLook at this. The Maya lived in southern Mexico, Guatemala and Belize. They built independent city states such as Tikal and Copan with tall stepped pyramids. They developed a writing system of glyphs, a calendar and a number system with the idea of zero. Their astronomers tracked the sun, moon and planets. Psalm eight and three says, When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained. Around nine hundred many southern Maya cities were abandoned. Scholars point to drought, war, overuse of land and political collapse, and the debate continues.\n\nYour task today. Match each culture to a place. Name three Maya achievements. And explain two ideas about the Maya decline. Take the four question check.\n\nWherever people study the heavens, they can see the Creator's hand. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 The Olmec, Zapotec, Chavin and Maya$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 The Aztec and Inca Empires$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Two great empires stood in the Americas when Europeans arrived.\n\nThe Aztec, or Mexica, founded Tenochtitlan around 1325 on an island in Lake Texcoco, now beneath Mexico City. They built causeways, canals, markets and floating gardens called chinampas. In 1428 the Aztec joined with two other cities in a Triple Alliance and conquered neighbors, who paid tribute. Aztec religion included large scale human sacrifice, which made conquered peoples hate and fear them. Moctezuma II ruled when Spanish explorers arrived in 1519.\n\nThe Inca ruled the Andes from their capital Cusco. Under Pachacuti, from about 1438, they expanded into a vast empire stretching along the western coast of South America. They built about 25,000 miles of roads and rope bridges, and they used a system of knotted cords called quipu for record keeping. They farmed steep mountain terraces and required citizens to give labor to the state, called the mita. The emperor was believed to be a child of the sun. Atahualpa was emperor when the Spanish arrived in 1532.\n\nThough many Aztec and Inca practices were harsh, their engineering, farming and organization were impressive. Genesis 1:27 says, So God created man in his own image, in the image of God created he him; male and female created he them. Every people, ancient and modern, bears that image, and every life has worth.\n\nYour task: (1) Tell where Tenochtitlan stood and how it was built. (2) Name three Inca achievements. (3) Compare how the Aztec and Inca ruled conquered peoples.\n\nFlorida standards: SS.912.W.3.18, SS.912.W.3.19.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.18, SS.912.W.3.19", "script": "Welcome back. Listen, two great empires stood in the Americas when Europeans arrived.\n\nNow watch this. The Aztec, also called the Mexica, founded Tenochtitlan around thirteen twenty five on an island in Lake Texcoco, now beneath Mexico City. They built causeways, canals, markets and floating gardens called chinampas. In fourteen twenty eight they joined two other cities in a Triple Alliance and conquered their neighbors, who paid tribute. Aztec religion included large scale human sacrifice, and conquered peoples hated and feared them. Moctezuma the Second ruled when the Spanish arrived in fifteen nineteen.\n\nLook at this. The Inca ruled the Andes from their capital Cusco. Under Pachacuti, from about fourteen thirty eight, they built a vast empire along the western coast of South America. They built about twenty five thousand miles of roads and rope bridges, and kept records on knotted cords called quipu. They farmed steep mountain terraces and required labor service to the state, called the mita. The emperor was believed to be a child of the sun. Atahualpa was emperor when the Spanish arrived in fifteen thirty two.\n\nMany of their practices were harsh, yet their engineering, farming and organization were impressive. Genesis one and twenty seven says, So God created man in his own image, in the image of God created he him; male and female created he them. Every people bears that image, and every life has worth.\n\nYour task today. Tell where Tenochtitlan stood. Name three Inca achievements. And compare how the Aztec and Inca ruled. Take the four question check.\n\nAll people are made in God's image. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 The Aztec and Inca Empires$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Africa and the Americas Research Report$j$, $j${"prompt": "Write a research report on one African kingdom and one American civilization from this unit. Use complete sentences and label each part. Genesis 1:27 says, So God created man in his own image, in the image of God created he him; male and female created he them.\n\nPart 1: Choose one African kingdom (Ghana, Mali, Songhai, Axum or Ethiopia, a Swahili city state, Great Zimbabwe or Kongo). Describe its location, source of wealth, government and religion.\nPart 2: Name two rulers of African states and explain why each was important.\nPart 3: Explain two reasons African states rose and two reasons they declined.\nPart 4: Choose one American civilization (Olmec, Zapotec, Chavin, Maya, Aztec or Inca). Describe its location, food, government, religion and one achievement.\nPart 5: Compare the Aztec and Inca empires in how they governed and kept records.\nPart 6: Write a paragraph explaining what the people of these regions show us about human dignity and creativity.", "rubric": "70 points. African kingdom description: 12 points. Rulers: 8 points. Rise and decline of African states: 10 points. American civilization description: 12 points. Aztec and Inca comparison: 12 points. Dignity paragraph: 12 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Africa and the Americas Research Report$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Wealth, Wisdom and Worth$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains how trade across the Sahara or the Indian Ocean helped African kingdoms grow, (2) describes one achievement of the Maya, Aztec or Inca that impressed you, (3) tells why we should study African and American history as part of world history, and (4) connects your answer to Proverbs 22:1, which says, A good name is rather to be chosen than great riches, and loving favour rather than silver and gold. Then write a respectful reply of at least 40 words to another student, or answer this question: What can a ruler like Mansa Musa teach us about using wealth? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Wealth, Wisdom and Worth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Gold and Salt Empires of West Africa$j$, $j${"questions": [{"q": "Ghana grew rich by taxing the trade in:", "options": ["Gold and salt", "Spices from Japan", "Silk and tea", "Tobacco and corn"]}, {"q": "Mansa Musa is famous for his:", "options": ["Conquest of Spain", "Voyage to America", "Invention of the compass", "Pilgrimage to Mecca in 1324"]}, {"q": "Which city became a center of learning in Mali and Songhai?", "options": ["Rome", "Timbuktu", "Kyoto", "Baghdad"]}, {"q": "Songhai fell in 1591 to an army from:", "options": ["Morocco with firearms", "Japan", "Mexico", "Portugal alone by sea"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Gold and Salt Empires of West Africa$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,0}'::int[], array[$j$Gold from the south and salt from the Sahara were exchanged.$j$,$j$He gave out so much gold that prices changed in Cairo.$j$,$j$Timbuktu was a trade and study center.$j$,$j$Moroccan guns broke Songhai's forces at Tondibi.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Gold and Salt Empires of West Africa$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Ethiopia, the Swahili Coast, Great Zimbabwe and Kongo$j$, $j${"questions": [{"q": "Which kingdom became Christian in the 300s under King Ezana?", "options": ["Mali", "Songhai", "Ghana", "Axum"]}, {"q": "Kilwa and Mombasa were:", "options": ["Viking towns", "Japanese ports", "Swahili trading city states", "Aztec capitals"]}, {"q": "Great Zimbabwe was built by the:", "options": ["Maya", "Franks", "Shona people", "Normans"]}, {"q": "Afonso I of Kongo:", "options": ["Built Timbuktu", "Led the Crusades", "Ruled Axum", "Accepted Christianity and opposed the enslavement of his people"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Ethiopia, the Swahili Coast, Great Zimbabwe and Kongo$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,2,3}'::int[], array[$j$Axum, later part of Ethiopia, adopted Christianity early.$j$,$j$They traded across the Indian Ocean.$j$,$j$The Shona built massive stone walls.$j$,$j$He wrote to Portugal protesting the slave trade.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Ethiopia, the Swahili Coast, Great Zimbabwe and Kongo$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: The Olmec, Zapotec, Chavin and Maya$j$, $j${"questions": [{"q": "The Olmec are famous for:", "options": ["Huge carved stone heads", "Steam engines", "Gothic cathedrals", "The Great Wall"]}, {"q": "Monte Alban was a center of the:", "options": ["Franks", "Inca", "Zapotec", "Songhai"]}, {"q": "The Maya developed:", "options": ["The printing press", "Gunpowder and the compass", "Glyph writing, a calendar and the idea of zero", "Paper money"]}, {"q": "Chavin de Huantar was a religious center in:", "options": ["The Andes of Peru", "Japan", "Persia", "West Africa"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: The Olmec, Zapotec, Chavin and Maya$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,0}'::int[], array[$j$Olmec colossal heads are well known.$j$,$j$It stood on a mountaintop in Oaxaca.$j$,$j$Maya mathematics and astronomy were advanced.$j$,$j$Chavin influenced later Andean cultures.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: The Olmec, Zapotec, Chavin and Maya$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: The Aztec and Inca Empires$j$, $j${"questions": [{"q": "Tenochtitlan was the capital of the:", "options": ["Aztec", "Olmec", "Maya", "Inca"]}, {"q": "The Inca recorded information using:", "options": ["Paper money", "Printed books", "Hieroglyphic stone", "Knotted cords called quipu"]}, {"q": "The Inca capital was:", "options": ["Cusco", "Kilwa", "Monte Alban", "Tikal"]}, {"q": "The Aztec Triple Alliance formed in:", "options": ["1066", "1428", "1519", "1215"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Aztec and Inca Empires$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,1}'::int[], array[$j$It stood in Lake Texcoco, where Mexico City is today.$j$,$j$Quipu stored numbers and records.$j$,$j$Cusco was the center of the empire.$j$,$j$Three cities joined to expand and collect tribute.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Aztec and Inca Empires$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: The Kingdoms of Africa and the Civilizations of the Americas$j$, $j${"questions": [{"q": "The trade that made Ghana, Mali and Songhai rich centered on:", "options": ["Wheat and wine", "Coffee and sugar", "Gold and salt", "Silk and porcelain"]}, {"q": "Sundiata Keita founded the empire of:", "options": ["Mali", "Ghana", "Axum", "Kongo"]}, {"q": "Lalibela is famous for:", "options": ["An Inca road", "Gold mines in Mali", "A Maya pyramid", "Rock carved churches in Ethiopia"]}, {"q": "The Maya city states included:", "options": ["Kyoto and Nara", "Tikal and Copan", "Cusco and Lima", "Kilwa and Mombasa"]}, {"q": "The Aztec built their capital on:", "options": ["An island in Lake Texcoco", "The Nile", "The Bosporus", "A mountaintop in Peru"]}, {"q": "The Inca built about 25,000 miles of:", "options": ["Roads", "Railroads", "Walls in Mexico", "Canals to the Pacific"]}, {"q": "The Swahili Coast traded across the:", "options": ["Mediterranean only", "Indian Ocean", "Atlantic Ocean", "Arctic Ocean"]}, {"q": "Genesis 1:27 teaches that:", "options": ["Only some nations have worth", "People are accidents", "Kings are gods", "Every person is made in God's image"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: The Kingdoms of Africa and the Civilizations of the Americas$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,1,0,0,1,3}'::int[], array[$j$Caravans carried gold and salt across the Sahara.$j$,$j$He defeated a rival around 1235.$j$,$j$The churches were carved from solid rock.$j$,$j$Tikal and Copan were major Maya cities.$j$,$j$Tenochtitlan used causeways and chinampas.$j$,$j$A road system linked the empire.$j$,$j$Monsoon winds carried ships to Arabia, India and China.$j$,$j$God created man in his own image.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: The Kingdoms of Africa and the Civilizations of the Americas$j$ on conflict (item_id) do nothing;
